# RUN: llvm-mc -triple=powerpc-unknown-eabi -mcpu=e200z4 -mattr=+vle -show-encoding %s \
# RUN:   | FileCheck %s
# Expected encodings come from NXP GNU as 2.28 (-mvle -me200z4), generated by
# plans/e200/tools/gen_mc_test.py.
# R-form instructions (VLEPEM Rev. 0 Figure A-6).  RX names r0-r7 and
# r24-r31.

# CHECK: se_not 0 # encoding: [0x00,0x20]
se_not 0
# CHECK: se_not 31 # encoding: [0x00,0x2f]
se_not 31
# CHECK: se_neg 7 # encoding: [0x00,0x37]
se_neg 7
# CHECK: se_neg 24 # encoding: [0x00,0x38]
se_neg 24
# CHECK: se_extzb 3 # encoding: [0x00,0xc3]
se_extzb 3
# CHECK: se_extsb 3 # encoding: [0x00,0xd3]
se_extsb 3
# CHECK: se_extzh 3 # encoding: [0x00,0xe3]
se_extzh 3
# CHECK: se_extsh 3 # encoding: [0x00,0xf3]
se_extsh 3
# CHECK: se_mflr 3 # encoding: [0x00,0x83]
se_mflr 3
# CHECK: se_mtlr 25 # encoding: [0x00,0x99]
se_mtlr 25
# CHECK: se_mfctr 3 # encoding: [0x00,0xa3]
se_mfctr 3
# CHECK: se_mtctr 30 # encoding: [0x00,0xbe]
se_mtctr 30
